import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {temperatureRows,bondCases,bondAccount} from './thermal-models.js?v=20261023-physicscomplete01';
const txt=(x,y,s,size=15,c='#f8f6f2')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${size}">${s}</text>`;
export function temperatureFigure(rows=temperatureRows){const x=v=>75+(v-.25)/.5*285,y=v=>230-v/10*170;return `<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="Illustrative neutralisation data: temperature rises3.0,6.1 and9.0 degrees Celsius at acid concentrations0.25,0.50 and0.75 moles per cubic decimetre. Other conditions controlled."><path d="M55 35V230H395" fill="none" stroke="currentColor"/>${[0,5,10].map(v=>`<path d="M55 ${y(v)}H395" stroke="currentColor" stroke-opacity=".15"/>${txt(35,y(v)+5,String(v),14,'currentColor')}`).join('')}<polyline points="${rows.map(r=>`${x(r.concentration)},${y(r.maximum-r.initial)}`).join(' ')}" fill="none" stroke="#ed8b78" stroke-width="3"/>${rows.map(r=>`<circle cx="${x(r.concentration)}" cy="${y(r.maximum-r.initial)}" r="5" fill="#ed8b78"/>${txt(x(r.concentration),254,r.concentration.toFixed(2),14,'currentColor')}`).join('')}${txt(220,18,'Temperature rise / °C',17,'currentColor')}${txt(220,285,'Acid concentration / mol/dm³',16,'currentColor')}</svg>`;}
export function showThermal(kind='apparatus',t=null,a={},reveal=false){
 if(kind==='bonds'){t??=bondCases[0];const acc=bondAccount(t.rows);const bond=(r,x,y)=>{const atom=r.label.split(/[–=≡]/);return `<g>${Array.from({length:r.order},(_,i)=>`<path d="M${x-23} ${y+(i-(r.order-1)/2)*5}H${x+23}" stroke="#b7c8d6" stroke-width="3"/>`).join('')}<circle cx="${x-34}" cy="${y}" r="19" fill="url(#thermalBall)"/><circle cx="${x+34}" cy="${y}" r="19" fill="#b7c8d6"/>${txt(x-34,y+5,atom[0],13,'#182e44')}${txt(x+34,y+5,atom[1],13,'#182e44')}${txt(x,y+40,r.label+' × '+(a[r.key]!==''&&a[r.key]!==undefined&&Number.isFinite(Number(a[r.key]))?Number(a[r.key]):'?'),15)}</g>`;};renderDiagram('Count the bonds first',t.equation,`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${t.equation}. Supplied bond types shown with student-entered counts; taken-in and released totals are revealed only after a correct account."><defs><radialGradient id="thermalBall" cx=".3" cy=".2"><stop stop-color="#f8f6f2"/><stop offset=".4" stop-color="#ed8b78"/><stop offset="1" stop-color="#b56959"/></radialGradient></defs>${txt(125,25,'Break · energy in',16)}${txt(330,25,'Form · energy out',16)}${t.rows.filter(r=>r.side==='break').map((r,i)=>bond(r,125,82+i*105)).join('')}${t.rows.filter(r=>r.side==='form').map((r,i)=>bond(r,330,82+i*105)).join('')}${txt(220,285,reveal?`${acc.broken} − ${acc.formed} = ${acc.overall} kJ/mol`:'One bond symbol represents the entered count',13)}</svg><p class="diagram-caption">Symbolic bonds, not a reaction mechanism. Supplied mean gas-phase bond energies are approximate.</p>`,'BOND-ENERGY ACCOUNT · SYMBOLIC MULTIPLICITIES');return;}
 if(kind==='data'){const table='<table class="aqueous-observations"><caption>Illustrative neutralisation trials</caption><thead><tr><th>Acid / mol/dm³</th><th>Initial / °C</th><th>Maximum / °C</th></tr></thead><tbody>'+temperatureRows.map(r=>`<tr><td>${r.concentration.toFixed(2)}</td><td>${r.initial.toFixed(1)}</td><td>${r.maximum.toFixed(1)}</td></tr>`).join('')+'</tbody></table>';renderDiagram('Compare the temperature rises','Fixed volumes · sufficient alkali',reveal?temperatureFigure():table,'ILLUSTRATIVE DATA · NOT A SCHOOL PRACTICAL RECORD');return;}
 if(kind==='evaluate'){renderDiagram('Check the method','Repeats: +8.0, +8.2, +14.0°C',`<svg class="lab-svg" viewBox="0 0 440 260" role="img" aria-label="Three repeated temperature rises8.0,8.2 and14.0 degrees Celsius. The higher repeat needs investigation, not automatic deletion.">${[8,8.2,14].map((v,i)=>`<rect x="${85+i*100}" y="${210-v*10}" width="45" height="${v*10}" rx="5" fill="${i===2?'#ed8b78':'#b7c8d6'}"/>${txt(107+i*100,235,'Trial '+(i+1),14)}${txt(107+i*100,195-v*10,'+'+v.toFixed(1)+'°C',14)}`).join('')}</svg>`,'REPEAT COMPARISON · ILLUSTRATIVE DATA');return;}
 renderDiagram('Measure with less heat loss','Insulated cup · lid · temperature probe',`<svg class="lab-svg" viewBox="0 0 440 290" role="img" aria-label="Schematic insulated polystyrene cup supported in a beaker with a lid and temperature probe. Record initial and extreme temperatures; mix gently under school supervision."><path d="M95 105V250H345V105" fill="#b7c8d611" stroke="#b7c8d6" stroke-width="2"/><path d="M128 105L150 230H290L312 105" fill="#ed8b7833" stroke="#f8f6f2" stroke-width="3"/><path d="M120 100H320" stroke="#f8f6f2" stroke-width="8"/><path d="M220 45V180" stroke="#b7c8d6" stroke-width="8"/><circle cx="220" cy="185" r="8" fill="#ed8b78"/>${txt(295,45,'Probe',15)}${txt(345,91,'Lid',15)}${txt(220,271,'Cup supported inside beaker',15)}</svg><p class="diagram-caption">Schematic apparatus, not to scale. Follow the supervised school method; this activity records reasoning only.</p>`,'TEMPERATURE PRACTICAL PREPARATION');
}
